412:   #[napi]
413:   pub fn encode_stream<'env>(
414:     &'env mut self,
415:     env: &Env,
416:     mime: Option<String>,
417:     quality: Option<u8>,
418:   ) -> Result<ReadableStream<'env, BufferSlice<'env>>> {
419:     // Flush deferred rendering before encoding
420:     self.ctx.context.flush();
421:     let mime = match mime.as_deref() {
422:       Some("webp") => sk::SkEncodedImageFormat::Webp,
423:       Some("jpeg") => sk::SkEncodedImageFormat::Jpeg,
424:       Some("png") | None => sk::SkEncodedImageFormat::Png,
425:       _ => return Err(Error::new(Status::InvalidArg, "Invalid mime")),
426:     };
427:     let (tx, rx) = channel(1024);
428:     let callback = |buffer: &[u8]| match tx.try_send(Ok(buffer.to_vec())) {
429:       Ok(_) | Err(TrySendError::Closed(_)) => {}
430:       Err(TrySendError::Full(_)) => {
431:         eprintln!("encode_image_stream_callback: channel is full");
432:       }
433:     };
434:     if !self.encode_image_inner(mime, quality.unwrap_or(DEFAULT_JPEG_QUALITY), callback) {
435:       return Err(Error::new(
436:         Status::GenericFailure,
437:         "Encode image stream failed",
438:       ));
439:     }
440:     ReadableStream::create_with_stream_bytes(env, ReceiverStream::new(rx))
441:   }
442: 
443:   // let the compiler infer the type of the callback
444:   fn encode_image_inner<F: Fn(&[u8])>(
445:     &self,
446:     mime: sk::SkEncodedImageFormat,
447:     quality: u8,
448:     callback: F,
449:   ) -> bool {
450:     let ptr = Box::into_raw(Box::new(callback));
451:     let result = self.ctx.context.surface.encode_stream(
452:       mime,
453:       quality,
454:       Some(encode_image_stream_callback::<F>),
455:       ptr.cast(),
456:     );
457:     // SAFETY: encode_stream is synchronous, so the callback is no longer referenced.
458:     // Recover the Box to free the allocation.
459:     unsafe { drop(Box::from_raw(ptr)) };
460:     result
461:   }
