3121:   pub fn ellipse(
3122:     &mut self,
3123:     x: f32,
3124:     y: f32,
3125:     radius_x: f32,
3126:     radius_y: f32,
3127:     rotation: f32,
3128:     start_angle: f32,
3129:     end_angle: f32,
3130:     ccw: bool,
3131:   ) {
3132:     // based off of CanonicalizeAngle in Chrome
3133:     let tau = 2.0 * PI;
3134:     let mut new_start_angle = start_angle % tau;
3135:     if new_start_angle < 0.0 {
3136:       new_start_angle += tau;
3137:     }
3138:     let delta = new_start_angle - start_angle;
3139:     let start_angle = new_start_angle;
3140:     let mut end_angle = end_angle + delta;
3141: 
3142:     // Based off of AdjustEndAngle in Chrome.
3143:     if !ccw && (end_angle - start_angle) >= tau {
3144:       end_angle = start_angle + tau; // Draw complete ellipse
3145:     } else if ccw && (start_angle - end_angle) >= tau {
3146:       end_angle = start_angle - tau; // Draw complete ellipse
3147:     } else if !ccw && start_angle > end_angle {
3148:       end_angle = start_angle + (tau - (start_angle - end_angle) % tau);
3149:     } else if ccw && start_angle < end_angle {
3150:       end_angle = start_angle - (tau - (end_angle - start_angle) % tau);
3151:     }
3152: 
3153:     // Based off of Chrome's implementation in
3154:     // https://cs.chromium.org/chromium/src/third_party/blink/renderer/platform/graphics/path.cc
3155:     // of note, can't use addArc or addOval because they close the arc, which
3156:     // the spec says not to do (unless the user explicitly calls closePath).
3157:     // This throws off points being in/out of the arc.
3158:     let left = x - radius_x;
3159:     let top = y - radius_y;
3160:     let right = x + radius_x;
3161:     let bottom = y + radius_y;
3162:     let mut rotated = Matrix::identity();
3163:     rotated.pre_translate(x, y);
3164:     rotated.pre_rotate(radians_to_degrees(rotation));
3165:     rotated.pre_translate(-x, -y);
3166:     let unrotated = rotated.invert().unwrap();
3167: 
3168:     self.transform_self(&unrotated);
3169: 
3170:     // draw in 2 180 degree segments because trying to draw all 360 degrees at once
3171:     // draws nothing.
3172:     let sweep_deg = radians_to_degrees(end_angle - start_angle);
3173:     let start_deg = radians_to_degrees(start_angle);
3174:     if almost_equal(sweep_deg.abs(), 360.0) {
3175:       let half_sweep = sweep_deg / 2.0;
3176:       self.arc_to(left, top, right, bottom, start_deg, half_sweep, false);
3177:       self.arc_to(
3178:         x - radius_x,
3179:         y - radius_y,
3180:         x + radius_x,
3181:         y + radius_y,
3182:         start_deg + half_sweep,
3183:         half_sweep,
3184:         false,
3185:       );
3186:     } else {
3187:       self.arc_to(left, top, right, bottom, start_deg, sweep_deg, false);
3188:     }
3189: 
3190:     self.transform_self(&rotated);
3191:   }
