  pub fn draw_text(
    &mut self,
    text: &str,
    x: f32,
    y: f32,
    max_width: f32,
    canvas_width: f32,
    weight: u32,
    stretch: i32,
    stretch_width: f32,
    slant: FontStyle,
    font_collection: &FontCollection,
    font_size: f32,
    font_family: &str,
    baseline: TextBaseline,
    align: TextAlign,
    direction: TextDirection,
    letter_spacing: f32,
    word_spacing: f32,
    paint: &Paint,
    variations: &[FontVariation],
    kerning: FontKerning,
    variant_caps: FontVariantCaps,
    lang: &str,
    text_rendering: TextRendering,
  ) -> Result<(), NulError> {
    let c_text = std::ffi::CString::new(text)?;
    let c_font_family = std::ffi::CString::new(font_family)?;
    // Convert lang to C string, or null if empty/"inherit"
    let c_lang = if lang.is_empty() || lang == "inherit" {
      None
    } else {
      Some(std::ffi::CString::new(lang)?)
    };

    unsafe {
      ffi::skiac_canvas_get_line_metrics_or_draw_text(
        c_text.as_ptr(),
        text.len(),
        max_width,
        x,
        y,
        canvas_width,
        font_collection.0,
        font_size,
        weight as i32,
        stretch,
        stretch_width,
        slant as i32,
        c_font_family.as_ptr(),
        baseline as i32,
        align as i32,
        direction.as_sk_direction(),
        letter_spacing,
        word_spacing,
        paint.0,
        self.0,
        ptr::null_mut(),
        variations.as_ptr() as *const ffi::skiac_font_variation,
        variations.len() as i32,
        kerning as i32,
        variant_caps as i32,
        c_lang.as_ref().map_or(ptr::null(), |s| s.as_ptr()),
        text_rendering as i32,
      );
    };
    Ok(())
  }

  pub fn get_line_metrics(
    &self,
    text: &str,
    font_collection: &FontCollection,
    font_size: f32,
    weight: u32,
    stretch: i32,
    stretch_width: f32,
    slant: FontStyle,
    font_family: &str,
    baseline: TextBaseline,
    align: TextAlign,
    direction: TextDirection,
    letter_spacing: f32,
    word_spacing: f32,
    paint: &Paint,
    variations: &[FontVariation],
    kerning: FontKerning,
    variant_caps: FontVariantCaps,
    lang: &str,
    text_rendering: TextRendering,
  ) -> Result<ffi::skiac_line_metrics, NulError> {
    let c_text = std::ffi::CString::new(text)?;
    let c_font_family = std::ffi::CString::new(font_family)?;
    // Convert lang to C string, or null if empty/"inherit"
    let c_lang = if lang.is_empty() || lang == "inherit" {
      None
    } else {
      Some(std::ffi::CString::new(lang)?)
    };

    let mut line_metrics = ffi::skiac_line_metrics::default();

    unsafe {
      ffi::skiac_canvas_get_line_metrics_or_draw_text(
        c_text.as_ptr(),
        text.len(),
        0.0,
        0.0,
        0.0,
        0.0,
        font_collection.0,
        font_size,
        weight as i32,
        stretch,
        stretch_width,
        slant as i32,
        c_font_family.as_ptr(),
        baseline as i32,
        align as i32,
        direction.as_sk_direction(),
        letter_spacing,
        word_spacing,
        paint.0,
        ptr::null_mut(),
        &mut line_metrics,
        variations.as_ptr() as *const ffi::skiac_font_variation,
        variations.len() as i32,
        kerning as i32,
        variant_caps as i32,
        c_lang.as_ref().map_or(ptr::null(), |s| s.as_ptr()),
        text_rendering as i32,
      );
    }
    Ok(line_metrics)
  }

